export type TextAlignmentHorizontal = "left" | "center" | "right" | "justify";
export type TextAlignmentVertical = "top" | "middle" | "bottom";
/** Text to render: a string, or spans that each override the node's text style. */
export type TextContent = string | readonly TextSpan[];
export type TextFit = "none" | "shrink";
export type TextFontStyle = "normal" | "italic" | "oblique";
export type TextHighlight = {
  /**
   * Start and end of the box along the text, as fractions of its width. An expression
   * gives both as one `vec2`, not one per element.
   */
  readonly extent?: ExpressionValue<Vec2>;
  /**
   * Horizontal and vertical padding around the text in pixels. An expression gives both as
   * one `vec2`, not one per element.
   */
  readonly padding?: ExpressionValue<Vec2>;
  /** Box color. */
  readonly paint?: ExpressionValue<Paint>;
  /** Corner radius in pixels. */
  readonly radius?: ExpressionValue<number>;
};
export type TextLine = {
  /**
   * Start and end of the line along the text, as fractions of its width. An expression
   * gives both as one `vec2`, not one per element.
   */
  readonly extent?: ExpressionValue<Vec2>;
  /**
   * Line position in pixels below the baseline; negative values are above it. Absent uses
   * the font's underline or strikethrough position.
   */
  readonly offset?: ExpressionValue<number>;
  /** Line color. Absent uses the text color. */
  readonly paint?: ExpressionValue<Paint>;
  /** Line style. */
  readonly style?: ExpressionValue<TextLineStyle>;
  /** Line thickness in pixels. Absent uses the font's. */
  readonly thickness?: ExpressionValue<number>;
};
export type TextLineStyle = "solid" | "double" | "dotted" | "dashed" | "wavy";
export type TextOverflow = "clip" | "ellipsis";
export type TextPaintSpace = "span" | "text";
export type TextRenderMode = "raster" | "msdf" | "auto";
export type TextSpan = {
  /**
   * Pixels the span's glyphs and its own decorations sit above the baseline; negative
   * values sit below it. The line keeps its height, so shifted text can overlap the
   * lines around it.
   */
  readonly baseline_shift?: ExpressionValue<number>;
  /** Text color. */
  readonly color?: ExpressionValue<Paint>;
  /** Font family name. */
  readonly font_family?: ExpressionValue<string>;
  /**
   * OpenType features, merged over the node's: a feature set here wins and the others are
   * kept. Within a word, the first span's features apply to all of it.
   */
  readonly font_features?: FontFeatures;
  /**
   * Font size in pixels. Where spans of one family, weight and style meet, a ligature or
   * other cluster across the boundary takes the size of the span it starts in.
   */
  readonly font_size?: ExpressionValue<number>;
  /** Font style. */
  readonly font_style?: ExpressionValue<TextFontStyle>;
  /** Font weight. Variable fonts render any value in their weight range. */
  readonly font_weight?: ExpressionValue<number>;
  /**
   * Box behind the text. `null` turns off the node's highlight. Its fields take literals or
   * expressions, but the whole highlight cannot be an expression.
   */
  readonly highlight?: TextHighlight | null;
  /** Extra space after every glyph in pixels. Negative values tighten the text. */
  readonly letter_spacing?: ExpressionValue<number>;
  /**
   * Line through the text. `null` turns off the node's strikethrough. Its fields take
   * literals or expressions, but the whole line cannot be an expression.
   */
  readonly strikethrough?: TextLine | null;
  /**
   * Outline along the glyphs. `null` turns off the node's stroke. Its fields take literals or
   * expressions, but the whole stroke cannot be an expression.
   */
  readonly stroke?: TextStroke | null;
  /** Text of the span. Required. */
  readonly text: ExpressionValue<string>;
  /** Case applied to the span's text. */
  readonly text_transform?: ExpressionValue<TextTransform>;
  /**
   * Line under the text. `null` turns off the node's underline. Its fields take literals or
   * expressions, but the whole line cannot be an expression.
   */
  readonly underline?: TextLine | null;
};
export type TextStroke = {
  /**
   * Where the outline lies: behind the glyphs and outside their edge, or over them and
   * centred on it.
   */
  readonly align?: ExpressionValue<TextStrokeAlign>;
  /** Outline color. */
  readonly paint?: ExpressionValue<Paint>;
  /** Outline width in pixels. */
  readonly width?: ExpressionValue<number>;
};
export type TextStrokeAlign = "outside" | "center";
export type TextTransform = "none" | "uppercase" | "lowercase" | "capitalize";
/** Length and frame rate. `fps` defaults to 30 at the root, and a template's timeline takes the root's `fps`. */
export type Timeline = {
  readonly duration_frames: number;
  readonly fps?: number;
};
export type TransformSampling = RasterSampling;

export interface CompositionNodeBase<TKind extends NodeKind> {
  readonly id: number;
  readonly type: TKind;
}

/** Generates a background raster texture. */
export interface BackgroundNode extends CompositionNodeBase<"background"> {
  readonly params?: {
    /** Output height in pixels. Use 0 to match the composition height. */
    readonly height?: number;
    /** Background paint. */
    readonly paint?: ExpressionValue<Paint>;
    /** Enables 4×4 supersampling when evaluating paint at each pixel. */
    readonly paint_supersample?: ExpressionValue<boolean>;
    /** Output width in pixels. Use 0 to match the composition width. */
    readonly width?: number;
  };
}

/** Applies a separable Gaussian blur to a raster. */
export interface BlurNode extends CompositionNodeBase<"blur"> {
  readonly params?: {
    /** Blur radius in pixels. Fractional radii blend smoothly. Radii above about 588 look the same. */
    readonly radius?: ExpressionValue<number>;
  };
}

/** Combines two raster alpha masks with boolean operations. */
export interface BooleanNode extends CompositionNodeBase<"boolean"> {
  readonly params?: {
    /** Boolean operation used to combine the two input masks. */
    readonly operation?: ExpressionValue<BooleanOperation>;
    /** Alpha above this cutoff counts as opaque; 0 applies no cutoff and keeps antialiased edges. */
    readonly threshold?: ExpressionValue<number>;
  };
}

/** Plays a composition template, or its source, over a window of time. */
export interface ClipNode extends CompositionNodeBase<"clip"> {
  readonly params?: {
    /** Template from `compositions` to play; empty plays the `source` input instead. */
    readonly composition?: string;
    /**
     * Frames the clip plays for; -1 plays the template to its end, or a source to the end of
     * this composition.
     */
    readonly duration?: ExpressionValue<number>;
    /** What the clip shows after its window: nothing, its last frame, or the window again. */
    readonly end?: ClipEnd;
    /** Frames of the content skipped at the start, in the content's frames. */
    readonly offset?: ExpressionValue<number>;
    /** Values for the template's props by name; expressions run in this composition's time. */
    readonly props?: ClipProps;
    /** Playback rate of the content; must be greater than 0. */
    readonly speed?: ExpressionValue<number>;
    /** Frame the clip starts at, in this composition's frames. */
    readonly start?: ExpressionValue<number>;
  };
}

/** Applies a LUT-driven color transform to a raster. */
export interface ColorGradeNode extends CompositionNodeBase<"color_grade"> {
  readonly params?: {
    /** Sampling filter used when reading LUT data. */
    readonly interpolation?: ExpressionValue<RasterSampling>;
    /** LUT data source or named LUT preset. */
    readonly lut_source?: ExpressionValue<string>;
    /** Blend amount for the LUT transform. */
    readonly strength?: ExpressionValue<number>;
  };
}

/** Keeps a raster region in place and clears everything outside it. */
export interface CropNode extends CompositionNodeBase<"crop"> {
  readonly params?: {
    /** Height of the crop region in pixels. */
    readonly height?: ExpressionValue<number>;
    /** Width of the crop region in pixels. */
    readonly width?: ExpressionValue<number>;
    /** Left edge of the crop region in pixels. */
    readonly x?: ExpressionValue<number>;
    /** Top edge of the crop region in pixels. */
    readonly y?: ExpressionValue<number>;
  };
}

/** Adjusts raster exposure, contrast, and offset. */
export interface ExposureNode extends CompositionNodeBase<"exposure"> {
  readonly params?: {
    /** Contrast multiplier. */
    readonly contrast?: ExpressionValue<number>;
    /** Exposure offset in stops. */
    readonly exposure?: ExpressionValue<number>;
    /** Linear color offset. */
    readonly offset?: ExpressionValue<number>;
  };
}

/** Adjusts raster hue, saturation, and lightness. */
export interface HueSaturationNode extends CompositionNodeBase<"hue_saturation"> {
  readonly params?: {
    /** Hue rotation in degrees. */
    readonly hue_degrees?: ExpressionValue<number>;
    /** Lightness offset. */
    readonly lightness?: ExpressionValue<number>;
    /** Saturation multiplier. */
    readonly saturation?: ExpressionValue<number>;
  };
}

/** Remaps raster black, white, gamma, and output range. */
export interface LevelsNode extends CompositionNodeBase<"levels"> {
  readonly params?: {
    /** Input black point. */
    readonly black_point?: ExpressionValue<number>;
    /** Midtone gamma adjustment. */
    readonly gamma?: ExpressionValue<number>;
    /** Output black level. */
    readonly output_black?: ExpressionValue<number>;
    /** Output white level. */
    readonly output_white?: ExpressionValue<number>;
    /** Input white point. */
    readonly white_point?: ExpressionValue<number>;
  };
}

/** Binds an external image or video frame as a GPU texture. */
export interface MediaInNode extends CompositionNodeBase<"media_in"> {
  readonly params?: {
    /** Type of external media source. */
    readonly kind?: ExpressionValue<MediaInSourceKind>;
    /** Behavior when playback leaves the source range. */
    readonly loop_mode?: ExpressionValue<LoopMode>;
    /** First source frame past the range; the source's end when unset. */
    readonly range_end?: ExpressionValue<number>;
    /** First source frame to include. */
    readonly range_start?: ExpressionValue<number>;
    /** External media source identifier. */
    readonly source?: ExpressionValue<string>;
    /** Playback speed multiplier. */
    readonly speed?: ExpressionValue<number>;
  };
}

/** Copies its source into the final composition output. */
export interface MediaOutputNode extends CompositionNodeBase<"media_output"> {
  readonly params?: Readonly<Record<string, never>>;
}

/** Composites an overlay raster over a base raster. */
export interface MergeNode extends CompositionNodeBase<"merge"> {
  readonly params?: {
    /** Blend mode used when combining the overlay with the base raster. */
    readonly blend_mode?: ExpressionValue<BlendMode>;
    /** Softens the mask edge with a Gaussian blur of this radius in pixels, applied before `invert`. Radii above about 588 look the same. */
    readonly feather?: ExpressionValue<number>;
    /** Swaps the masked and unmasked areas. */
    readonly invert?: ExpressionValue<boolean>;
    /** Channel of the `mask` input that controls overlay visibility. */
    readonly mask_mode?: MaskMode;
    /** Overlay opacity applied before compositing. */
    readonly opacity?: ExpressionValue<number>;
  };
}

/** Uniformly adjusts raster opacity. */
export interface OpacityNode extends CompositionNodeBase<"opacity"> {
  readonly params?: {
    /** Opacity multiplier applied to the raster. */
    readonly opacity?: ExpressionValue<number>;
  };
}

/** Produces a rasterized vector path source. */
export interface PathNode extends CompositionNodeBase<"path"> {
  readonly params?: {
    /** Pivot for scale and rotation, in pixels relative to `position`. */
    readonly anchor?: ExpressionValue<Vec2>;
    /** SVG-style path data. */
    readonly data?: ExpressionValue<string>;
    /** Enables analytic distance-based edge antialiasing. */
    readonly edge_antialias?: ExpressionValue<boolean>;
    /** Enables fill rendering. */
    readonly fill_enabled?: ExpressionValue<boolean>;
    /** Fill paint. Accepts a solid color or gradient. */
    readonly fill_paint?: ExpressionValue<Paint>;
    /**
     * Motion blur shutter angle in degrees, centred on the frame. 0 is off, 180 is the
     * usual film look and 360 smears over the whole frame.
     */
    readonly motion_blur?: ExpressionValue<number>;
    /** Opacity multiplier. */
    readonly opacity?: ExpressionValue<number>;
    /** Path origin in pixels. */
    readonly position?: ExpressionValue<Vec2>;
    /** Clockwise rotation in degrees, about the anchor. */
    readonly rotation?: ExpressionValue<number>;
    /** Scale multiplier per axis, about the anchor. */
    readonly scale?: ExpressionValue<Vec2>;
    /** Enables stroke rendering. */
    readonly stroke_enabled?: ExpressionValue<boolean>;
    /** Stroke paint. Accepts a solid color or gradient. */
    readonly stroke_paint?: ExpressionValue<Paint>;
    /**
     * Stroke width in untransformed pixels. Under non-uniform scale the stroke stretches
     * with the path, so it is wider across the more scaled axis.
     */
    readonly stroke_width?: ExpressionValue<number>;
    /** Normalized end of the visible stroke range for each contour. */
    readonly trim_end?: ExpressionValue<number>;
    /** Normalized start of the visible stroke range for each contour. */
    readonly trim_start?: ExpressionValue<number>;
  };
}

/** Composites a variadic stack of raster layers in order. */
export interface RasterMultimergeNode extends CompositionNodeBase<"raster_multimerge"> {
  readonly params?: {
    /** Blend mode used for each layer in the stack. */
    readonly blend_mode?: ExpressionValue<BlendMode>;
    /** Opacity of each layer above the first, which is the base and is used as is. */
    readonly opacity?: ExpressionValue<number>;
  };
}

/** Resamples a raster into a rectangle placed on the composition canvas. */
export interface ResizeNode extends CompositionNodeBase<"resize"> {
  readonly params?: {
    /** Output height in pixels. */
    readonly height?: ExpressionValue<number>;
    /** How the source raster should fit the output bounds. */
    readonly mode?: ResizeMode;
    /** Sampling filter used when resizing. */
    readonly sampling?: ExpressionValue<RasterSampling>;
    /** Output width in pixels. */
    readonly width?: ExpressionValue<number>;
    /** Left edge of the output rectangle in pixels. */
    readonly x?: ExpressionValue<number>;
    /** Top edge of the output rectangle in pixels. */
    readonly y?: ExpressionValue<number>;
  };
}

/** Composites a blurred alpha shadow behind a raster. */
export interface ShadowNode extends CompositionNodeBase<"shadow"> {
  readonly params?: {
    /** Shadow color. Must be a solid color; a gradient is an error. */
    readonly color?: ExpressionValue<Paint>;
    /** Horizontal shadow offset in pixels. */
    readonly offset_x?: ExpressionValue<number>;
    /** Vertical shadow offset in pixels. */
    readonly offset_y?: ExpressionValue<number>;
    /** Shadow opacity. */
    readonly opacity?: ExpressionValue<number>;
    /** Shadow blur radius in pixels. Fractional radii blend smoothly. Radii above about 588 look the same. */
    readonly radius?: ExpressionValue<number>;
  };
}

/** Produces a vector shape layer for GPU rasterization. */
export interface ShapeNode extends CompositionNodeBase<"shape"> {
  readonly params?: {
    /** Pivot for scale and rotation, in pixels relative to `position`. */
    readonly anchor?: ExpressionValue<Vec2>;
    /** Corner radius for rectangle geometry. */
    readonly border_radius?: ExpressionValue<number>;
    /** Enables analytic distance-based edge antialiasing. */
    readonly edge_antialias?: ExpressionValue<boolean>;
    /** Enables fill rendering. */
    readonly fill_enabled?: ExpressionValue<boolean>;
    /** Fill paint. Accepts a solid color or gradient. */
    readonly fill_paint?: ExpressionValue<Paint>;
    /** Geometry primitive to rasterize. */
    readonly geometry_kind?: ShapeGeometryKind;
    /**
     * Shape height in pixels; 0 draws nothing and anything thinner than a pixel draws a pixel
     * tall.
     */
    readonly height?: ExpressionValue<number>;
    /**
     * Motion blur shutter angle in degrees, centred on the frame. 0 is off, 180 is the
     * usual film look and 360 smears over the whole frame.
     */
    readonly motion_blur?: ExpressionValue<number>;
    /** Opacity multiplier. */
    readonly opacity?: ExpressionValue<number>;
    /** Shape origin in pixels. */
    readonly position?: ExpressionValue<Vec2>;
    /** Clockwise rotation in degrees, about the anchor. */
    readonly rotation?: ExpressionValue<number>;
    /** Scale multiplier per axis, about the anchor. */
    readonly scale?: ExpressionValue<Vec2>;
    /** Enables stroke rendering. */
    readonly stroke_enabled?: ExpressionValue<boolean>;
    /** Stroke paint. Accepts a solid color or gradient. */
    readonly stroke_paint?: ExpressionValue<Paint>;
    /**
     * Stroke width in untransformed pixels. Under non-uniform scale the stroke stretches
     * with the shape, so it is wider across the more scaled axis.
     */
    readonly stroke_width?: ExpressionValue<number>;
    /**
     * Shape width in pixels; 0 draws nothing and anything thinner than a pixel draws a pixel
     * wide.
     */
    readonly width?: ExpressionValue<number>;
  };
}

/** Selects one raster input according to a controlled layer index. */
export interface SwitchNode extends CompositionNodeBase<"switch"> {
  readonly params?: {
    /** Zero-based input index to route to the output. */
    readonly selected_layer?: ExpressionValue<number>;
  };
}

/** Produces a text source. */
export interface TextNode extends CompositionNodeBase<"text"> {
  readonly params?: {
    /** Horizontal text alignment. */
    readonly alignment_horizontal?: TextAlignmentHorizontal;
    /** Vertical text alignment. */
    readonly alignment_vertical?: TextAlignmentVertical;
    /** Pivot for scale and rotation, in pixels relative to `position`. */
    readonly anchor?: ExpressionValue<Vec2>;
    /** Text color, and that of spans without their own. */
    readonly color?: ExpressionValue<Paint>;
    /**
     * Text to render: a string, or spans that each override the style these params give. A
     * node draws at most 2048 glyphs, counting a stroked glyph twice and each decoration rect
     * once; whitespace is not drawn, and more is a render error.
     */
    readonly content?: ExpressionValue<TextContent>;
    /**
     * Whether the text shrinks to fit `max_width`, `max_lines` and `max_height` without breaking
     * a word, before any lines are dropped. Every font size, letter spacing, `line_height`,
     * baseline shift, paragraph spacing, decoration size and stroke width scales by the largest
     * factor up to 1 that fits.
     */
    readonly fit?: TextFit;
    /** Font family name. */
    readonly font_family?: ExpressionValue<string>;
    /**
     * OpenType features by four-character tag, such as `{ "tnum": 1, "liga": 0 }`. 0 turns a
     * feature off, 1 turns it on and larger values select an alternate. Values take literals
     * or expressions, but the whole map cannot be an expression.
     */
    readonly font_features?: FontFeatures;
    /** Font size in pixels. */
    readonly font_size?: ExpressionValue<number>;
    /** Font style. */
    readonly font_style?: ExpressionValue<TextFontStyle>;
    /** Font weight. Variable fonts render any value in their weight range. */
    readonly font_weight?: ExpressionValue<number>;
    /**
     * Offset of each glyph in pixels. The `glyph_*` params are evaluated for every glyph,
     * and can read its `glyph`, `word`, `line` and `span` index and their counts.
     */
    readonly glyph_offset?: ExpressionValue<Vec2>;
    /** Opacity multiplier of each glyph, applied before `opacity`. */
    readonly glyph_opacity?: ExpressionValue<number>;
    /** Clockwise rotation of each glyph in degrees, about the middle of its advance and line. */
    readonly glyph_rotation?: ExpressionValue<number>;
    /** Scale multiplier of each glyph per axis, about the middle of its advance and line. */
    readonly glyph_scale?: ExpressionValue<Vec2>;
    /**
     * Box behind each line of the text, and of spans that leave theirs unset. Off when
     * absent.
     */
    readonly highlight?: TextHighlight;
    /** Extra space after every glyph in pixels. Negative values tighten the text. */
    readonly letter_spacing?: ExpressionValue<number>;
    /** Distance between lines in pixels. Use 0 for 1.2 × the font size. */
    readonly line_height?: ExpressionValue<number>;
    /** Most height in pixels of the lines to show. Unlimited when absent. */
    readonly max_height?: ExpressionValue<number>;
    /** Most lines to show. Unlimited when absent. */
    readonly max_lines?: ExpressionValue<number>;
    /** Maximum line width in pixels. Use 0 for automatic width. */
    readonly max_width?: ExpressionValue<number>;
    /**
     * Smallest `font_size` that `fit` shrinks the text to. Lines that still do not fit are
     * dropped by `overflow`.
     */
    readonly min_font_size?: ExpressionValue<number>;
    /**
     * Motion blur shutter angle in degrees, centred on the frame. 0 is off, 180 is the
     * usual film look and 360 smears over the whole frame. Blurs the text's own movement,
     * not that of the `glyph_*` params.
     */
    readonly motion_blur?: ExpressionValue<number>;
    /** Opacity multiplier. */
    readonly opacity?: ExpressionValue<number>;
    /**
     * How the last line shown ends when lines past `max_lines` or `max_height` are dropped: as
     * it is, or in an ellipsis. Clusters at that line's end are dropped until the ellipsis fits
     * `max_width`. The ellipsis takes the style and paint of the text it follows, and is one
     * glyph, numbered after the last one shown.
     */
    readonly overflow?: TextOverflow;
    /**
     * Box a span's own gradient `color` spans: the span's lines, or the whole text. The
     * node's `color` always spans the whole text.
     */
    readonly paint_space?: TextPaintSpace;
    /** Enables 4×4 supersampling when evaluating paint at each glyph pixel. */
    readonly paint_supersample?: ExpressionValue<boolean>;
    /**
     * Extra space in pixels after each paragraph, but the last. A line break starts a new
     * paragraph.
     */
    readonly paragraph_spacing?: ExpressionValue<number>;
    /** Text origin in pixels. */
    readonly position?: ExpressionValue<Vec2>;
    /** Glyph rendering mode. MSDF reuses outline distance fields across sizes; Auto is MSDF from 512 px. */
    readonly render_mode?: TextRenderMode;
    /** Clockwise rotation in degrees, about the anchor. */
    readonly rotation?: ExpressionValue<number>;
    /**
     * Scale multiplier per axis, about the anchor. Raster glyphs are resampled, so
     * use MSDF rendering to keep scaled text sharp.
     */
    readonly scale?: ExpressionValue<Vec2>;
    /** Line through the text, and through spans that leave theirs unset. Off when absent. */
    readonly strikethrough?: TextLine;
    /**
     * Outline along the glyphs, and along those of spans that leave theirs unset. Off when
     * absent. It does not change the layout or the measured size. `glyph_opacity` fades a
     * glyph's stroke and fill as one.
     */
    readonly stroke?: TextStroke;
    /** Case applied to the text, and to spans that leave theirs unset. */
    readonly text_transform?: ExpressionValue<TextTransform>;
    /**
     * Line under the text, and under spans that leave theirs unset. Off when absent. Its
     * fields take literals or expressions, but the whole line cannot be an expression.
     */
    readonly underline?: TextLine;
  };
}

/** Evaluates a raster input at another frame. */
export interface TimeRemapNode extends CompositionNodeBase<"time_remap"> {
  readonly params?: {
    /** Source frame to sample. */
    readonly frame?: ExpressionValue<number>;
    /** Enables looping between the configured loop bounds. */
    readonly loop_enabled?: ExpressionValue<boolean>;
    /** Last frame in the loop range. */
    readonly loop_end?: ExpressionValue<number>;
    /** First frame in the loop range. */
    readonly loop_start?: ExpressionValue<number>;
  };
}

/** Transforms a raster into the composition canvas bounds. */
export interface TransformNode extends CompositionNodeBase<"transform"> {
  readonly params?: {
    /** Uses the pivot as given; when off, the pivot is the source centre. */
    readonly custom_pivot?: ExpressionValue<boolean>;
    /**
     * Motion blur shutter angle in degrees, centred on the frame. 0 is off, 180 is the
     * usual film look and 360 smears over the whole frame.
     */
    readonly motion_blur?: ExpressionValue<number>;
    /** Horizontal pivot point in pixels. */
    readonly pivot_x?: ExpressionValue<number>;
    /** Vertical pivot point in pixels. */
    readonly pivot_y?: ExpressionValue<number>;
    /** Rotation in degrees. */
    readonly rotate?: ExpressionValue<number>;
    /** Sampling filter used when transforming. */
    readonly sampling?: ExpressionValue<RasterSampling>;
    /** Horizontal scale multiplier. */
    readonly scale_x?: ExpressionValue<number>;
    /** Vertical scale multiplier. */
    readonly scale_y?: ExpressionValue<number>;
    /** Horizontal translation in pixels. */
    readonly translate_x?: ExpressionValue<number>;
    /** Vertical translation in pixels. */
    readonly translate_y?: ExpressionValue<number>;
  };
}

/** Runs a custom WGSL compute shader over one or more rasters. */
export interface WgslShaderNode extends CompositionNodeBase<"wgsl_shader"> {
  readonly params?: {
    /** WGSL compute shader; the prelude provides inputs, `input_sampler`, `output` and `lumen`. */
    readonly shader?: ExpressionValue<string>;
    /** Uniform struct field values by name; unset fields are zero. */
    readonly uniforms?: ShaderUniforms;
  };
}

export interface CompositionNodeByKind {
  readonly "background": BackgroundNode;
  readonly "blur": BlurNode;
  readonly "boolean": BooleanNode;
  readonly "clip": ClipNode;
  readonly "color_grade": ColorGradeNode;
  readonly "crop": CropNode;
  readonly "exposure": ExposureNode;
  readonly "hue_saturation": HueSaturationNode;
  readonly "levels": LevelsNode;
  readonly "media_in": MediaInNode;
  readonly "media_output": MediaOutputNode;
  readonly "merge": MergeNode;
  readonly "opacity": OpacityNode;
  readonly "path": PathNode;
  readonly "raster_multimerge": RasterMultimergeNode;
  readonly "resize": ResizeNode;
  readonly "shadow": ShadowNode;
  readonly "shape": ShapeNode;
  readonly "switch": SwitchNode;
  readonly "text": TextNode;
  readonly "time_remap": TimeRemapNode;
  readonly "transform": TransformNode;
  readonly "wgsl_shader": WgslShaderNode;
}

